// Normaliza la entrada del dispatcher y evalúa las dos guardas de recursión.
//
// Varios flujos existentes llaman a sub-workflows con convertFieldsToString:true,
// que convierte los objetos en strings JSON (por eso Billing.json arranca con un
// JSON.parse). Toleramos ambas formas para que instrumentar un flujo no dependa
// de acertar ese flag.
const asObj = (v) => {
  if (v === null || v === undefined) return {};
  if (typeof v === 'string') { const s = v.trim(); return s ? JSON.parse(s) : {}; }
  return v;
};
const asArr = (v) => {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string') { const s = v.trim(); if (!s) return []; const p = JSON.parse(s); return Array.isArray(p) ? p : []; }
  return [];
};

const MAX_DEPTH = 5;

const inp = $input.first().json;

const event_code = (inp.event_code || '').toString().trim();
if (!event_code) {
  throw new Error('hooks-dispatcher: event_code es obligatorio');
}

const payload   = asObj(inp.payload);
const context   = asObj(inp.context);
const hook_path = asArr(inp.hook_path);
const depth     = Number.isFinite(Number(inp.depth)) ? Number(inp.depth) : 0;

const clinic_id = (inp.clinic_id === null || inp.clinic_id === undefined || inp.clinic_id === '')
  ? null
  : Number(inp.clinic_id);

const correlation_id = (inp.correlation_id || $execution.id || '').toString();

// Guarda 1: profundidad. Un hook que dispara un evento que dispara el mismo
// hook es el clásico. Guarda 2: ciclo explícito en la cadena de eventos.
let guard = null;
if (depth >= MAX_DEPTH)            guard = 'max_depth';
else if (hook_path.includes(event_code)) guard = 'cycle';

return [{ json: {
  event_code,
  payload,
  context,
  hook_path,
  depth,
  clinic_id,
  correlation_id,
  guard,
  guard_ok: guard === null,
  started_at: Date.now(),
} }];

// Convierte las filas del registry en una cola de un item por hook, cada uno con
// los metadatos de despacho que necesitan los nodos de abajo.
const base = $('Normalizar Entrada').first().json;

return $input.all()
  .filter((it) => it.json && it.json.registry_id)
  .map((it) => {
    const r = it.json;
    const asObj = (v) => {
      if (v === null || v === undefined) return {};
      if (typeof v === 'string') { const s = v.trim(); return s ? JSON.parse(s) : {}; }
      return v;
    };
    return { json: {
      registry_id:     r.registry_id,
      name:            r.name,
      handler_type:    r.handler_type,
      handler_ref:     r.handler_ref,
      seq:             Number(r.seq),
      mode:            r.mode,
      on_error:        r.on_error,
      timeout_ms:      Number(r.timeout_ms),
      config:          asObj(r.config),
      log_enabled:     r.log_enabled === true,
      timing:          r.timing,
      payload_version: Number(r.payload_version),
      event_code:      base.event_code,
    } };
  });

// Arma el envelope que recibe ESTE hook.
//
// Semántica del encadenamiento: dentro de un mismo evento los hooks corren en
// orden de `seq` y cada uno ve el payload ya parcheado por los anteriores. El
// patch acumulado se lee de la corrida anterior de 'Acumular Resultado'
// (índice de corrida explícito, no la resolución implícita de item, que dentro
// de un splitInBatches es ambigua).
//
// Si esa lectura fallara en alguna versión de n8n, el catch degrada el
// comportamiento a "cada hook ve el payload original" — nunca corrompe datos, y
// el patch que devuelve el dispatcher sigue siendo correcto porque
// 'Fusionar Resultados' lo recalcula desde cero.
const hook = $input.first().json;
const base = $('Normalizar Entrada').first().json;

let acc = {};
if ($runIndex > 0) {
  try {
    const prev = $('Acumular Resultado').all(0, $runIndex - 1);
    acc = (prev && prev[0] && prev[0].json && prev[0].json.acc_patch) ? prev[0].json.acc_patch : {};
  } catch (e) {
    acc = {};
  }
}

// Merge SUPERFICIAL a propósito. Un deep merge de arrays es donde este tipo de
// mecanismo se vuelve impredecible; gana el hook de `seq` más alto.
const payload = { ...base.payload, ...acc };

return [{ json: {
  ...hook,
  acc_patch: acc,
  envelope: {
    hook_envelope_version: 1,
    event_code:      base.event_code,
    timing:          hook.timing,
    payload_version: hook.payload_version,
    payload,
    context: {
      ...base.context,
      correlation_id: base.correlation_id,
      clinic_id:      base.clinic_id,
    },
    config:      hook.config,
    registry_id: hook.registry_id,
    depth:       base.depth + 1,
    hook_path:   [...base.hook_path, base.event_code],
  },
  started_at: Date.now(),
} }];

// Salida de error de cualquiera de los dos nodos Execute Sub-workflow.
const e = $input.first().json || {};
const msg = e.error?.message || e.message || e.error || 'El hook falló sin mensaje';
return [{ json: { ok: false, patch: {}, error: String(msg) } }];

// Normaliza lo que haya devuelto el hook (o el manejador de error) a una forma
// única, y arrastra el patch acumulado para la siguiente iteración.
const MAX_LOG_CHARS = 8192;
const truncate = (v) => {
  try {
    const s = JSON.stringify(v ?? null);
    if (s === null || s === undefined) return null;
    if (s.length <= MAX_LOG_CHARS) return JSON.parse(s);
    return { _truncated: true, _chars: s.length };
  } catch (e) {
    return { _unserializable: true };
  }
};

const it   = $input.first().json || {};
const prep = $('Preparar Iteración').all(0, $runIndex)[0].json;

const isAsync = prep.mode === 'async';

// El nodo async devuelve SU ENTRADA, no la salida del hook: n8n no espera. Por
// eso un hook asíncrono nunca puede aportar un patch, y por eso los eventos
// 'before' tienen prohibido mode='async' (se rechaza al registrarlos).
const ok = it.ok === false ? false : true;

const patch = (!isAsync && ok && it.patch && typeof it.patch === 'object' && !Array.isArray(it.patch))
  ? it.patch
  : {};

return [{ json: {
  registry_id: prep.registry_id,
  name:        prep.name,
  handler_ref: prep.handler_ref,
  seq:         prep.seq,
  mode:        prep.mode,
  on_error:    prep.on_error,
  log_enabled: prep.log_enabled,
  event_code:  prep.event_code,
  depth:       prep.envelope.depth,
  ok,
  status:      ok ? 'success' : 'error',
  patch,
  error:       ok ? null : String(it.error || it.message || 'Hook failed'),
  duration_ms: Date.now() - prep.started_at,
  acc_patch:   { ...prep.acc_patch, ...patch },
  log_input:   truncate(prep.envelope),
  log_output:  truncate(isAsync ? { _async: true } : it),
  correlation_id: prep.envelope.context.correlation_id,
} }];

// 'Registrar Log' devuelve la salida de Postgres (o nada, si log_enabled era
// false), así que el resultado del hook se recupera explícitamente por índice de
// corrida antes de decidir si hay que abortar.
const r = $('Acumular Resultado').all(0, $runIndex)[0].json;
return [{ json: { ...r, must_abort: r.on_error === 'fail' && r.ok === false } }];

// Fin del bucle: recompone la salida del dispatcher.
//
// El patch final se RECALCULA aquí desde todos los resultados en orden de `seq`,
// en vez de confiar en el acumulador que se arrastra dentro del bucle. Es la red
// de seguridad: si la lectura cruzada entre corridas fallara, el patch devuelto
// al flujo llamante sigue siendo correcto.
const base = $('Normalizar Entrada').first().json;

const results = [];
for (let i = 0; ; i++) {
  let run;
  try { run = $('Acumular Resultado').all(0, i); } catch (e) { break; }
  if (!run || run.length === 0) break;
  results.push(run[0].json);
}

results.sort((a, b) => (a.seq - b.seq));

let patch = {};
for (const r of results) {
  if (r.ok && r.patch && typeof r.patch === 'object') patch = { ...patch, ...r.patch };
}

const failed = results.filter((r) => !r.ok).length;

return [{ json: {
  ok:             failed === 0,
  event_code:     base.event_code,
  executed:       results.length,
  succeeded:      results.length - failed,
  failed,
  skipped:        0,
  skipped_reason: null,
  patch,
  payload:        { ...base.payload, ...patch },
  results: results.map((r) => ({
    registry_id: r.registry_id,
    name:        r.name,
    handler_ref: r.handler_ref,
    seq:         r.seq,
    mode:        r.mode,
    ok:          r.ok,
    duration_ms: r.duration_ms,
    error:       r.error,
  })),
  duration_ms:    Date.now() - base.started_at,
  correlation_id: base.correlation_id,
} }];

// Camino "no hay nada que ejecutar": o el cliente no registró implementaciones,
// o saltó una guarda de recursión.
//
// Devuelve EXACTAMENTE la misma forma que 'Fusionar Resultados' para que el
// flujo llamante tenga un solo camino de código. `payload` sale sin tocar: ésta
// es la propiedad que hace seguro instrumentar los flujos comunes — sin hooks
// registrados, el comportamiento es idéntico al de antes.
const base = $('Normalizar Entrada').first().json;

// Si el SELECT del registry falló (BD caída, permisos, tabla inexistente) se
// sigue devolviendo el payload intacto: tumbar una facturación porque no se pudo
// leer la tabla de hooks sería peor que no ejecutarlos. Pero se deja constancia
// en skipped_reason en vez de fingir que simplemente no había nada registrado,
// que es indistinguible a simple vista y muy caro de depurar.
let reason = base.guard;
if (!reason) {
  try {
    const filas = $('Buscar Hooks').all();
    if (filas.length > 0 && filas[0].json && filas[0].json.error) reason = 'lookup_error';
  } catch (e) {
    // No se pasó por 'Buscar Hooks': saltó una guarda antes. base.guard ya lo dice.
  }
}

return [{ json: {
  ok:             reason !== 'lookup_error',
  event_code:     base.event_code,
  executed:       0,
  succeeded:      0,
  failed:         0,
  skipped:        reason ? 1 : 0,
  skipped_reason: reason,
  patch:          {},
  payload:        base.payload,
  results:        [],
  duration_ms:    Date.now() - base.started_at,
  correlation_id: base.correlation_id,
} }];
